using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Diagnostics;
namespace KianaPet {
 public sealed class ExternalTaskEvent {public int Schema=1;public string EventId=Guid.NewGuid().ToString("N"),Source,TaskId,Title,Status,OpenPath;public DateTime At=DateTime.UtcNow;}
 public sealed class TaskReceipt {public string Key,EventId,Status;public DateTime At;}
 public sealed class ExternalTaskInbox {
  readonly string root;readonly TaskNoticeHub hub;readonly Dictionary<string,TaskReceipt> receipts=new Dictionary<string,TaskReceipt>();
  readonly Dictionary<string,Tuple<string,string>> registered=new Dictionary<string,Tuple<string,string>>();
  public string Status="尚未接收外部任务";
  static int Rank(string state){return state=="succeeded"||state=="failed"?2:state=="waiting"?1:0;}
  public ExternalTaskInbox(string stateRoot,TaskNoticeHub target){root=stateRoot;hub=target;try{foreach(var r in Store.Json.Deserialize<TaskReceipt[]>(File.ReadAllText(Path.Combine(root,"external-task-receipts.json"))).Where(r=>r!=null&&r.Key!=null).Take(256))receipts[r.Key]=r;}catch{}}
  public static void Validate(ExternalTaskEvent e){if(e==null||e.Schema!=1||string.IsNullOrEmpty(e.EventId)||e.EventId.Length>64||e.At.Kind==DateTimeKind.Unspecified)throw new Exception("无效任务事件。");if(e.Source=="ChatGPT"||e.Source=="专注计时")throw new Exception("请为外部任务使用独立来源名称。");var check=new TaskNoticeHub();check.Publish(new TaskNotice{Source=e.Source,TaskId=e.TaskId,Title=e.Title,Status=e.Status});if(!string.IsNullOrEmpty(e.OpenPath)){if(e.OpenPath.Length>1024||e.OpenPath.Any(char.IsControl)||e.OpenPath.IndexOf('"')>=0||!Path.IsPathRooted(e.OpenPath)||e.OpenPath.Contains("://")||e.OpenPath.StartsWith(@"\\?\"))throw new Exception("输出路径必须是普通绝对文件或目录路径。");e.OpenPath=Path.GetFullPath(e.OpenPath);}}
  public static void Write(string stateRoot,ExternalTaskEvent e){Validate(e);string folder=Path.Combine(stateRoot,"task-inbox");Directory.CreateDirectory(folder);if(Directory.EnumerateFiles(folder,"*.json").Take(201).Count()>=200)throw new Exception("任务收件箱已满，请启用桌宠中的外部任务接收。");string final=Path.Combine(folder,Guid.NewGuid().ToString("N")+".json"),tmp=final+".tmp";File.WriteAllText(tmp,Store.Json.Serialize(e),new UTF8Encoding(false));File.Move(tmp,final);}
  public int Drain(){string folder=Path.Combine(root,"task-inbox");if(!Directory.Exists(folder))return 0;int accepted=0;var pending=new List<Tuple<string,ExternalTaskEvent>>();foreach(var file in Directory.EnumerateFiles(folder,"*.json").OrderBy(p=>p,StringComparer.Ordinal).Take(100)){try{if(new FileInfo(file).Length>16384)throw new Exception("任务事件超过 16 KB。");var e=Store.Json.Deserialize<ExternalTaskEvent>(File.ReadAllText(file));Validate(e);if(e.At.ToUniversalTime()>DateTime.UtcNow.AddMinutes(2)||e.At.ToUniversalTime()<DateTime.UtcNow.AddHours(-24))throw new Exception("任务事件已过期或时间无效。");pending.Add(Tuple.Create(file,e));}catch(Exception ex){Status="已拒绝一条无效事件："+ex.Message;File.Delete(file);}}
   foreach(var pair in pending.OrderBy(p=>p.Item2.At).ThenBy(p=>Rank(p.Item2.Status)).ThenBy(p=>p.Item2.EventId,StringComparer.Ordinal)){var e=pair.Item2;string key=e.Source.Length+":"+e.Source+e.TaskId;TaskReceipt prior;bool newer=!receipts.TryGetValue(key,out prior)||e.At>prior.At||e.At==prior.At&&(Rank(e.Status)>Rank(prior.Status)||Rank(e.Status)==Rank(prior.Status)&&string.CompareOrdinal(e.EventId,prior.EventId)>0);if(newer){string action="external-"+SharedPreferences.Hash(Encoding.UTF8.GetBytes(key)).Substring(0,24);if(!string.IsNullOrEmpty(e.OpenPath)){string path=e.OpenPath;hub.RegisterAction(e.Source,action,delegate{if(!File.Exists(path)&&!Directory.Exists(path))throw new Exception("输出路径已不存在。");Process.Start(new ProcessStartInfo{FileName="explorer.exe",Arguments=Directory.Exists(path)?"\""+path+"\"":"/select,\""+path+"\"",UseShellExecute=false});});}else hub.UnregisterAction(e.Source,action);registered[key]=Tuple.Create(e.Source,action);
     hub.Publish(new TaskNotice{Source=e.Source,TaskId=e.TaskId,Title=e.Title,Status=e.Status,ActionId=string.IsNullOrEmpty(e.OpenPath)?null:action});var live=hub.Snapshot();foreach(var stale in registered.Where(p=>!live.Any(n=>n.Source==p.Value.Item1&&n.ActionId==p.Value.Item2)).Select(p=>p.Key).ToArray()){hub.UnregisterAction(registered[stale].Item1,registered[stale].Item2);registered.Remove(stale);}receipts[key]=new TaskReceipt{Key=key,At=e.At,EventId=e.EventId,Status=e.Status};accepted++;Status="最近接收："+e.Source+" · "+TaskNoticeHub.StateName(e.Status)+" · "+DateTime.Now.ToString("HH:mm:ss");}
    while(receipts.Count>256)receipts.Remove(receipts.Values.OrderBy(r=>r.At).First().Key);string ledger=Path.Combine(root,"external-task-receipts.json"),temp=ledger+".tmp";File.WriteAllText(temp,Store.Json.Serialize(receipts.Values.ToArray()),new UTF8Encoding(false));if(File.Exists(ledger))File.Replace(temp,ledger,null);else File.Move(temp,ledger);File.Delete(pair.Item1);
   }return accepted;
  }
  public static int ReceiveCommand(string[] args,string root){try{var values=new Dictionary<string,string>();for(int i=0;i<args.Length;i++){if(args[i]=="--task-notice")continue;if(i+1>=args.Length||!new[]{"--state-dir","--source","--task-id","--title","--status","--open-path"}.Contains(args[i]))throw new Exception("未知任务通知参数。");values.Add(args[i],args[++i]);}Func<string,string> get=k=>values.ContainsKey(k)?values[k]:null;if(!values.ContainsKey("--state-dir"))throw new Exception("--state-dir is required.");Write(Path.GetFullPath(values["--state-dir"]),new ExternalTaskEvent{Source=get("--source"),TaskId=get("--task-id"),Title=get("--title"),Status=get("--status"),OpenPath=get("--open-path")});return 0;}catch{return 2;}}
 }
}
